The script below reads any CSV with `user_*` columns and `order_*` columns, strips those prefixes into nested objects, groups multiple rows for the same user into one record, and emits JSON shaped like:

```json
[
  {
    "user": {
      "name": "Alice",
      "email": "alice@example.com"
    },
    "orders": [
      {
        "id": 1001,
        "item": "Widget",
        "price": 9.99
      }
    ]
  }
]
```

It uses `csv.DictReader` for quoting/escaping support, handles missing fields, extra columns, empty values, and basic scalar type coercion.

```python
#!/usr/bin/env python3

import csv
import json
import re
import sys
from collections import OrderedDict


RESTKEY = "__extra_fields__"


_INT_RE = re.compile(r"^[+-]?(?:0|[1-9]\d*)$")
_FLOAT_RE = re.compile(
    r"^[+-]?(?:(?:\d+\.\d*)|(?:\.\d+)|(?:\d+))(?:[eE][+-]?\d+)$|"
    r"^[+-]?(?:(?:\d+\.\d*)|(?:\.\d+))$"
)


def strip_prefix(name, prefix):
    """Remove a known prefix from a column name."""
    if name.startswith(prefix):
        stripped = name[len(prefix):]
        return stripped or name
    return name


def coerce_value(value):
    """
    Convert common CSV scalar strings into JSON-friendly Python values.

    Rules:
    - Empty strings and common null tokens become None.
    - true/false become booleans.
    - Integer-looking values become int, except numbers with leading zeroes
      are kept as strings to avoid corrupting IDs/ZIP-like values.
    - Float-looking values become float.
    - Everything else remains a string.
    """
    if value is None:
        return None

    if not isinstance(value, str):
        return value

    s = value.strip()

    if s == "":
        return None

    lower = s.lower()
    if lower in {"null", "none", "nil", "n/a", "na"}:
        return None
    if lower == "true":
        return True
    if lower == "false":
        return False

    # Avoid emitting non-standard JSON NaN/Infinity.
    if lower in {"nan", "+nan", "-nan", "inf", "+inf", "-inf", "infinity", "+infinity", "-infinity"}:
        return s

    if _INT_RE.match(s):
        signless = s[1:] if s[0] in "+-" else s
        if len(signless) > 1 and signless.startswith("0"):
            return s
        try:
            return int(s)
        except ValueError:
            return s

    if _FLOAT_RE.match(s):
        try:
            return float(s)
        except ValueError:
            return s

    return s


def has_meaningful_value(obj):
    """Return True if any field in a dictionary/list contains a non-empty value."""
    if isinstance(obj, dict):
        return any(has_meaningful_value(v) for v in obj.values())
    if isinstance(obj, list):
        return any(has_meaningful_value(v) for v in obj)
    return obj is not None


def build_nested_json(input_path):
    with open(input_path, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f, restkey=RESTKEY, restval="")

        if not reader.fieldnames:
            return []

        fieldnames = [name for name in reader.fieldnames if name is not None]

        user_columns = [c for c in fieldnames if c.startswith("user_")]
        order_columns = [c for c in fieldnames if c.startswith("order_")]

        # Preserve non-prefixed columns rather than silently dropping them.
        other_columns = [
            c for c in fieldnames
            if c not in user_columns and c not in order_columns
        ]

        grouped = OrderedDict()

        for row_number, row in enumerate(reader, start=2):
            user_obj = OrderedDict()
            for col in user_columns:
                user_obj[strip_prefix(col, "user_")] = coerce_value(row.get(col, ""))

            order_obj = OrderedDict()
            for col in order_columns:
                order_obj[strip_prefix(col, "order_")] = coerce_value(row.get(col, ""))

            # If a related CSV has unprefixed columns, preserve them under
            # "_extra" on the order when possible, otherwise on the user record.
            extra_obj = OrderedDict()
            for col in other_columns:
                val = coerce_value(row.get(col, ""))
                if val is not None:
                    extra_obj[col] = val

            # Inconsistent rows with too many CSV fields are captured here by
            # csv.DictReader via restkey.
            extra_fields = row.get(RESTKEY)
            if extra_fields:
                extra_obj[RESTKEY] = [coerce_value(v) for v in extra_fields]

            if extra_obj:
                if order_columns:
                    order_obj["_extra"] = extra_obj
                else:
                    user_obj["_extra"] = extra_obj

            # Group repeated users together. If a row has no meaningful user
            # data, keep it separate so unrelated anonymous rows are not merged.
            if has_meaningful_value(user_obj):
                group_key = tuple((k, json.dumps(v, sort_keys=True, ensure_ascii=False)) for k, v in user_obj.items())
            else:
                group_key = ("__anonymous_row__", row_number)

            if group_key not in grouped:
                grouped[group_key] = {
                    "user": user_obj,
                    "orders": []
                }

            if has_meaningful_value(order_obj):
                grouped[group_key]["orders"].append(order_obj)

        return list(grouped.values())


def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} INPUT_CSV OUTPUT_JSON", file=sys.stderr)
        sys.exit(2)

    input_path = sys.argv[1]
    output_path = sys.argv[2]

    data = build_nested_json(input_path)

    with open(output_path, "w", encoding="utf-8", newline="") as f:
        json.dump(data, f, ensure_ascii=False, indent=2, allow_nan=False)
        f.write("\n")


if __name__ == "__main__":
    main()
```
